package ru.folio.notes;

import java.util.*;
import java.awt.*;
import java.awt.image.BufferedImage;
import javax.imageio.ImageIO;
import java.io.File;

public final class ColorPickerTests {
    static int checks;static void check(boolean yes,String why){checks++;if(!yes)throw new AssertionError(why);}
    static void values(){Random random=new Random(171);for(int i=0;i<20000;i++){int color=0xff000000|random.nextInt(0x1000000);ColorModel model=new ColorModel(color);check(model.color()==color,"exact RGB/HSL round trip");check(ColorModel.parse(ColorModel.hex(color))==color,"HEX round trip");}check(ColorModel.rgb(0,1,.5f)==0xffff0000,"red");check(ColorModel.rgb(120,1,.5f)==0xff00ff00,"green");check(ColorModel.rgb(240,1,.5f)==0xff0000ff,"blue");check(ColorModel.rgb(360,1,.5f)==0xffff0000,"hue wraps");check(ColorModel.rgb(40,1,0)==0xff000000&&ColorModel.rgb(200,1,1)==-1,"black and white endpoints");ColorModel model=new ColorModel(0xff00ff00);model.slider(1,0);check(model.hue==120,"desaturating retains useful hue");model.slider(1,1);check(model.color()==0xff00ff00,"restoring saturation retains hue");model.set(0xff777777);check(model.hue==120,"selecting gray retains last hue");check(ColorModel.parse(" #abc ")==0xffaabbcc,"short HEX");for(String bad:new String[]{"","#1234","#1234567","not-a-color","#ggffff"}){boolean failed=false;try{ColorModel.parse(bad);}catch(IllegalArgumentException expected){failed=true;}check(failed,"invalid HEX rejected");}}
    static void presets(){check(ColorDefaults.GRID.length==117,"117 reference colors");HashSet<Integer> colors=new HashSet<>();for(int i=0;i<117;i++){int color=ColorDefaults.GRID[i];check((color>>>24)==255,"opaque palette entries");colors.add(color);check(ColorDefaults.hit((i%13+.5f)*25,(i/13+.5f)*25,325,225)==i,"all grid cells map to their visible colors");}check(colors.size()==117,"reference entries unique");int previous=256;for(int row=0;row<9;row++){int color=ColorDefaults.GRID[row*13+12],r=(color>>16)&255;check(r==((color>>8)&255)&&r==(color&255)&&r<previous,"neutral column ordered white to black");previous=r;}check(Arrays.equals(ColorDefaults.forTool("pen"),new int[]{0xff1f1f1f,0xff1d39c4,0xffff4d4f}),"Mi Canvas ballpoint defaults");check(Arrays.equals(ColorDefaults.forTool("marker"),new int[]{0xffbae7ff,0xfffffb8f,0xffffd8bf}),"Mi Canvas marker defaults");check(Arrays.equals(ColorDefaults.forTool("pencil"),new int[]{0xff096dd9,0xff000000,0xffcf1322}),"Mi Canvas pencil defaults");check(Arrays.equals(ColorDefaults.forTool("brush"),new int[]{0xff87e8de,0xffffa39e,0xffffadd2}),"Mi Canvas watercolor defaults");int[] copy=ColorDefaults.forTool("pen");copy[0]=0;check(ColorDefaults.forTool("pen")[0]==0xff1f1f1f,"preset storage cannot be changed by caller");check(ColorDefaults.hit(-1,1,325,225)==-1&&ColorDefaults.hit(325,1,325,225)==-1&&ColorDefaults.hit(1,225,325,225)==-1&&ColorDefaults.hit(Float.NaN,1,325,225)==-1,"outside grid ignored");int[] recent={0xffff0000,0xff00ff00,0xff0000ff};check(Arrays.equals(ColorModel.recent(recent,0xff00ff00,3),new int[]{0xff00ff00,0xffff0000,0xff0000ff}),"recents promoted without duplication");check(ColorModel.recent(recent,0xffeeeeee,2).length==2,"recent history bounded");}
    static void preview(File file)throws Exception{BufferedImage image=new BufferedImage(1540,1080,BufferedImage.TYPE_INT_RGB);Graphics2D g=image.createGraphics();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setColor(new Color(0x101217));g.fillRect(0,0,1540,1080);g.scale(2,2);for(int mode=0;mode<2;mode++){Graphics2D c=(Graphics2D)g.create();c.translate(15+mode*380,15);c.setColor(new Color(0x202329));c.fillRoundRect(0,0,365,480,26,26);c.setColor(new Color(0xf4f2ed));c.setFont(new Font("SansSerif",Font.BOLD,18));c.drawString("Цвет",14,31);c.setColor(new Color(0x999eab));c.drawString("×",332,30);c.setColor(new Color(0x191c23));c.fillRoundRect(14,48,337,36,10,10);c.setColor(new Color(0x414550));c.fillRoundRect(17+mode*168,51,162,30,8,8);c.setFont(new Font("SansSerif",Font.PLAIN,12));c.setColor(new Color(0xf4f2ed));c.drawString("Сетка",75,71);c.drawString("Ползунки",231,71);if(mode==0){for(int i=0;i<117;i++){c.setColor(new Color(ColorDefaults.GRID[i]));int x=14+i%13*337/13,y=94+i/13*25;c.fillRect(x,y,(i%13+1)*337/13-i%13*337/13,25);}}else {ColorModel model=new ColorModel(0xff1d39c4);String[] labels={"Тон","Насыщенность","Светлота"};for(int row=0;row<3;row++){int y=108+row*70;c.setFont(new Font("SansSerif",Font.PLAIN,12));c.setColor(new Color(0xf4f2ed));c.drawString(labels[row],17,y);for(int x=0;x<315;x++){float t=x/314f;c.setColor(new Color(ColorModel.rgb(row==0?t*360:model.hue,row==1?t:row==0?1:model.saturation,row==2?t:row==0?.5f:model.lightness)));c.fillRect(25+x,y+21,1,10);}float f=row==0?model.hue/360:row==1?model.saturation:model.lightness;int x=25+Math.round(315*f);c.setColor(Color.WHITE);c.fillOval(x-7,y+19,14,14);}}c.setColor(new Color(0x999eab));c.setFont(new Font("SansSerif",Font.PLAIN,10));c.drawString("Готовые",14,343);int[] presets=ColorDefaults.forTool("pen");for(int i=0;i<3;i++){c.setColor(new Color(presets[i]));c.fillOval(247+i*38,328,21,21);}c.setColor(new Color(0x1d39c4));c.fillOval(20,370,22,22);c.setColor(new Color(0x292d35));c.fillRoundRect(56,364,295,36,12,12);c.setColor(new Color(0xf4f2ed));c.setFont(new Font("Monospaced",Font.PLAIN,13));c.drawString("#1D39C4",68,387);c.setColor(new Color(0x292d35));c.fillRoundRect(14,422,159,44,14,14);c.setColor(new Color(0xb5b3ff));c.fillRoundRect(183,422,168,44,14,14);c.setFont(new Font("SansSerif",Font.BOLD,13));c.setColor(new Color(0xf4f2ed));c.drawString("Отмена",69,449);c.setColor(new Color(0x15171c));c.drawString("Применить",227,449);c.dispose();}g.setColor(new Color(0x999eab));g.setFont(new Font("SansSerif",Font.PLAIN,10));g.drawString("Модель данных и компоновки палитры. Не снимок Android.",18,526);g.dispose();ImageIO.write(image,"png",file);}
    public static void main(String[] args)throws Exception{values();presets();preview(new File(args[0]));System.out.println("PASS "+checks+" color assertions: RGB/HSL and HEX, 117 reference cells, tool presets, bounds and recent history. Preview is a desktop model, not Android.");}
}
